import { execFileSync } from 'node:child_process'
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')
const files = [
  'imgcat',
  'imgls',
  'ofn-copy',
  'ofn-notify',
  'ofn-dl',
  'ofn-title',
  'ofn-check',
]
const tmp = mkdtempSync(join(root, 'build/utils-'))
const tgz = join(tmp, 'utilities.tgz')
try {
  execFileSync('tar', [...(process.platform === 'darwin' ? ['--no-xattrs'] : []), '--format=ustar', '-czf', tgz, '-C', join(root, 'contrib'), ...files], {
    env: { ...process.env, COPYFILE_DISABLE: '1' },
  })
  const base64 = readFileSync(tgz).toString('base64')
  const out = join(root, 'src/frontend/src/lib/utilities-bundle.ts')
  writeFileSync(out, `// Generated by scripts/build-utils-bundle.mjs; do not edit by hand.\nexport const UTILITIES_BUNDLE = '${base64}'\n`)
  console.log(`wrote ${out} (${base64.length} base64 chars)`)
} finally {
  rmSync(tmp, { recursive: true, force: true })
}
